#include <iostream>
#include <cstring>
#include <queue>
using namespace std;

struct Cell{int r,c,dis;};

const int dRow[4]={-1,0,1,0},dCol[4]={0,-1,0,1};
queue<Cell> q;
char line[15];
int vertexCount,source,sink,m,limit,totalPath,height[202],gap[203],capacity[202][202],currentFlow[202][202],pathStack[202];
bool visited[12][12],originalMap[12][12],pathExists;

void dfsPush(int u,int bottleneck){
  if(u==sink){
    height[0]=bottleneck;pathExists=true;return;
  }
  int minLevel=sink+2;
  for(int v=0;v<=sink+1;++v){
    if(currentFlow[u][v]<capacity[u][v]){
      minLevel=min(minLevel,height[v]);
      if(height[u]==height[v]+1){
        pathStack[++totalPath]=v;
        dfsPush(v,min(bottleneck,capacity[u][v]-currentFlow[u][v]));
        if(!visited[0][0]||pathExists)return;
        pathStack[totalPath--]=0;
      }
    }
    if(currentFlow[v][u]>0){
      minLevel=min(minLevel,height[v]);
      if(height[u]==height[v]+1){
        pathStack[++totalPath]=-v;
        dfsPush(v,min(bottleneck,currentFlow[v][u]));
        if(!visited[0][0]||pathExists)return;
        pathStack[totalPath--]=0;
      }
    }
  }
  if(minLevel+1!=height[u]){
    --gap[height[u]];
    if(gap[height[u]]==0)visited[0][0]=false;
    height[u]=minLevel+1;
    ++gap[height[u]];
  }
}

bool findAugmentingPath(){
  pathExists=false;height[0]=sink;totalPath=0;pathStack[0]=0;
  dfsPush(0,sink);return pathExists;
}

void updateFlow(){
  for(int i=1;i<=totalPath;++i){
    if(pathStack[i]>0)currentFlow[abs(pathStack[i-1])][pathStack[i]]+=height[0];
    else currentFlow[-pathStack[i]][abs(pathStack[i-1])]-=height[0];
  }
}

int main(){
  cin>>m>>limit;
  for(int i=1;i<=m;++i){
    cin>>line+1;
    for(int j=1;j<=m;++j){
      if(line[j]=='Z'){
        Cell start={i,j,0};q.push(start);
      }else if(line[j]!='Y'){
        visited[i][j]=true;originalMap[i][j]=true;
        dist[i][j]=limit;
        int val=line[j]-'0';
        if(val>0){
          a[i][j]=++vertexCount;
          capacity[0][vertexCount]=val;
          sink+=val;
        }
      }
    }
  }
  memcpy(originalMap,visited,sizeof(visited));
  for(int i=1;i<=m;++i){
    cin>>line+1;
    for(int j=1;j<=m;++j){
      if(line[j]=='Z'||line[j]=='Y')continue;
      int val=line[j]-'0';
      if(val>0){
        b[i][j]=++vertexCount;
        capacity[vertexCount][m*m+1]=val;
      }
    }
  }
  if(vertexCount!=m*m){
    for(int i=1;i<=m;++i)
      for(int j=1;j<=m;++j)
        if(b[i][j]>0){
          int idx=b[i][j];
          capacity[idx][vertexCount+1]=capacity[idx][m*m+1];
          capacity[idx][m*m+1]=0;
        }
  }
  while(!q.empty()){
    Cell cur=q.front();q.pop();
    int r=cur.r,c=cur.c;dist[r][c]=cur.dis;
    for(int k=0;k<4;++k)
      if(visited[r+dRow[k]][c+dCol[k]]){
        Cell next={r+dRow[k],c+dCol[k],cur.dis+1};q.push(next);
        visited[r+dRow[k]][c+dCol[k]]=false;
      }
  }
  for(int i=1;i<=m;++i)
    for(int j=1;j<=m;++j){
      if(a[i][j]==0)continue;
      memcpy(visited,originalMap,sizeof(originalMap));
      visited[i][j]=false;
      Cell start={i,j,0};q.push(start);
      while(!q.empty()){
        Cell cur=q.front();q.pop();
        int r=cur.r,c=cur.c;
        if(b[r][c]>0&&cur.dis<=dist[r][c])capacity[a[i][j]][b[r][c]]=sink;
        if(cur.dis+1>limit||cur.dis>=dist[r][c])continue;
        for(int k=0;k<4;++k)
          if(visited[r+dRow[k]][c+dCol[k]]){
            Cell next={r+dRow[k],c+dCol[k],cur.dis+1};q.push(next);
            visited[r+dRow[k]][c+dCol[k]]=false;
          }
      }
    }
  gap[0]=vertexCount+2;visited[0][0]=true;
  while(visited[0][0]&&height[0]<=vertexCount+2)
    while(findAugmentingPath())updateFlow();
  int result=0;
  for(int i=1;i<=vertexCount;++i)result+=currentFlow[i][vertexCount+1];
  cout<<result<<endl;return 0;
}
